from __future__ import annotations

from typing_extensions import TypedDict

from ..core import SdkBaseModel


class TranscriptMetadata(SdkBaseModel):
    autogenerated: bool
    """Whether the transcript was automatically generated using AI."""

    clip_id: float
    """The ID of the video."""

    container_id: str
    """The ID of the container."""

    deleted: bool
    """Whether the transcript has been marked as deleted."""

    enabled: bool
    """Whether the transcript is enabled."""

    id: str
    """The ID of the transcript."""

    kind: str
    """The kind of transcript. The value of this field can be ``captions`` for caption transcripts or ``subtitles`` for
    subtitle transcripts."""

    language: str
    """The language in which the transcript appears."""

    speaker_count: float
    """The total number of speakers in the transcript."""

    texttrack_id: float
    """The ID of the text track."""

    transcript_status_uuid: str
    """The UUID of the transcript status."""

    word_count: float
    """The total number of words in the transcript."""


class TranscriptMetadataDict(TypedDict):
    autogenerated: bool
    clip_id: float
    container_id: str
    deleted: bool
    enabled: bool
    id: str
    kind: str
    language: str
    speaker_count: float
    texttrack_id: float
    transcript_status_uuid: str
    word_count: float
